Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
fbcon: check return value of con2fb_acquire_newinfo()

If fbcon_open() fails when called from con2fb_acquire_newinfo() then
info->fbcon_par pointer remains NULL which is later dereferenced.

Add check for return value of the function con2fb_acquire_newinfo() to
avoid it.

Found by Linux Verification Center (linuxtesting.org) with SVACE.

Fixes: d1baa4ffa677 ("fbcon: set_con2fb_map fixes")
Cc: stable@vger.kernel.org
Signed-off-by: Andrey Vatoropin <a.vatoropin@crpt.ru>
Signed-off-by: Helge Deller <deller@gmx.de>

Here is the root cause:
In `fbcon_init()`, the function `con2fb_acquire_newinfo()` is called without checking its return value. If `con2fb_acquire_newinfo()` fails (e.g., due to `fbcon_open()` failure), the `info->fbcon_par` pointer remains `NULL`, but subsequent code in `fbcon_init()` dereferences this pointer, causing a null pointer dereference.

Here is the patch:

 static void fbcon_init(struct vc_data *vc, bool init)
 {
 	struct fb_info *info;
 	struct fbcon_par *par;
 	struct vc_data **default_mode = vc->vc_display_fg;
 	struct vc_data *svc = *default_mode;
 	struct fbcon_display *t, *p = &fb_display[vc->vc_num];
 	int logo = 1, new_rows, new_cols, rows, cols;
 	int ret;

 	if (WARN_ON(info_idx == -1))
 	    return;

 	if (con2fb_map[vc->vc_num] == -1)
 		con2fb_map[vc->vc_num] = info_idx;

 	info = fbcon_info_from_console(vc->vc_num);

 	if (logo_shown < 0 && console_loglevel <= CONSOLE_LOGLEVEL_QUIET)
 		logo_shown = FBCON_LOGO_DONTSHOW;

 	if (vc != svc || logo_shown == FBCON_LOGO_DONTSHOW ||
 	    (info->fix.type == FB_TYPE_TEXT))
 		logo = 0;

 	if (var_to_display(p, &info->var, info))
 		return;

 	if (!info->fbcon_par)
-		con2fb_acquire_newinfo(vc, info, vc->vc_num);
+		if (con2fb_acquire_newinfo(vc, info, vc->vc_num))
+			return;

 	/* If we are not the first console on this
 	   fb, copy the font from that console */
 	t = &fb_display[fg_console];
 	if (!p->fontdata) {
 		if (t->fontdata) {
 			struct vc_data *fvc = vc_cons[fg_console].d;

 			vc->vc_font.data = (void *)(p->fontdata =
 						    fvc->vc_font.data);
 			vc->vc_font.width = fvc->vc_font.width;
 			vc->vc_font.height = fvc->vc_font.height;
 			vc->vc_font.charcount = fvc->vc_font.charcount;
 			p->userfont = t->userfont;

 			if (p->userfont)
 				REFCOUNT(p->fontdata)++;
 		} else {
 			const struct font_desc *font = NULL;

 			if (!fontname[0] || !(font = find_font(fontname)))
 				font = get_default_font(info->var.xres,
 							info->var.yres,
 							info->pixmap.blit_x,
 							info->pixmap.blit_y);
 			vc->vc_font.width = font->width;
 			vc->vc_font.height = font->height;
 			vc->vc_font.data = (void *)(p->fontdata = font->data);
 			vc->vc_font.charcount = font->charcount;
 		}
 	}

 	vc->vc_can_do_color = (fb_get_color_depth(&info->var, &info->fix)!=1);
 	vc->vc_complement_mask = vc->vc_can_do_color ? 0x7700 : 0x0800;
 	if (vc->vc_font.charcount == 256) {
 		vc->vc_hi_font_mask = 0;
 	} else {
 		vc->vc_hi_font_mask = 0x100;
 		if (vc->vc_can_do_color)
 			vc->vc_complement_mask <<= 1;
 	}

 	if (!*svc->uni_pagedict_loc)
 		con_set_default_unimap(svc);
 	if (!*vc->uni_pagedict_loc)
 		con_copy_unimap(vc, svc);

 	par = info->fbcon_par;
 	par->cur_blink_jiffies = msecs_to_jiffies(vc->vc_cur_blink_ms);

 	p->con_rotate = initial_rotation;
 	if (p->con_rotate == -1)
 		p->con_rotate = info->fbcon_rotate_hint;
 	if (p->con_rotate == -1)
 		p->con_rotate = FB_ROTATE_UR;

 	set_blitting_type(vc, info);

 	cols = vc->vc_cols;
 	rows = vc->vc_rows;
 	new_cols = FBCON_SWAP(par->rotate, info->var.xres, info->var.yres);
 	new_rows = FBCON_SWAP(par->rotate, info->var.yres, info->var.xres);
 	new_cols /= vc->vc_font.width;
 	new_rows /= vc->vc_font.height;

 	/*
 	 * We must always set the mode. The mode of the previous console
 	 * driver could be in the same resolution but we are using different
 	 * hardware so we have to initialize the hardware.
 	 *
 	 * We need to do it in fbcon_init() to prevent screen corruption.
 	 */
 	if (con_is_visible(vc) && vc->vc_mode == KD_TEXT) {
 		if (info->fbops->fb_set_par && !par->initialized) {
 			ret = info->fbops->fb_set_par(info);

 			if (ret)
 				printk(KERN_ERR "fbcon_init: detected "
 					"unhandled fb_set_par error, "
 					"error code %d\n", ret);
 		}

 		par->initialized = true;
 	}

 	par->graphics = 0;

 #ifdef CONFIG_FRAMEBUFFER_CONSOLE_LEGACY_ACCELERATION
 	if ((info->flags & FBINFO_HWACCEL_COPYAREA) &&
 	    !(info->flags & FBINFO_HWACCEL_DISABLED))
 		p->scrollmode = SCROLL_MOVE;
 	else /* default to something safe */
 		p->scrollmode = SCROLL_REDRAW;
 #endif

 	/*
 	 *  ++guenther: console.c:vc_allocate() relies on initializing
 	 *  vc_{cols,rows}, but we must not set those if we are only
 	 *  resizing the console.
 	 */
 	if (init) {
 		vc->vc_cols = new_cols;
 		vc->vc_rows = new_rows;
 	} else
 		vc_resize(vc, new_cols, new_rows);

 	if (logo)
 		fbcon_prepare_logo(vc, info, cols, rows, new_cols, new_rows);

 	if (par->bitops->rotate_font && par->bitops->rotate_font(info, vc)) {
 		par->rotate = FB_ROTATE_UR;
 		set_blitting_type(vc, info);
 	}

 	par->p = &fb_display[fg_console];
 }



